source:
(sh) => {
    sh.uniforms.tDet = { value: tex }; sh.uniforms.uDet = { value: new THREE.Vector4(1 / scaleM, strength, gain, 0) };
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vWp;').replace('#include <begin_vertex>', '#include <begin_vertex>\nvWp = (modelMatrix * vec4(transformed, 1.0)).xyz;');
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vWp;\nuniform sampler2D tDet;\nuniform vec4 uDet;')
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
      { vec3 wn = abs(normalize(cross(dFdx(vWp), dFdy(vWp)))); vec2 p = wn.y > 0.6 ? vWp.xz : (wn.x > 0.6 ? vec2(vWp.z, vWp.y) : vWp.xy);
        vec3 d = texture2D(tDet, p * uDet.x).rgb * uDet.z; float lit = max(totalEmissiveRadiance.r, max(totalEmissiveRadiance.g, totalEmissiveRadiance.b));
        diffuseColor.rgb *= mix(vec3(1.0), d, uDet.y * (1.0 - smoothstep(0.02, 0.25, lit))); }`);
  }

